'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var toFloat32 = require( '@stdlib/number-float64-base-to-float32' );
var tryRequire = require( '@stdlib/utils-try-require' );


// VARIABLES //

var isSameValue = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( isSameValue instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof isSameValue, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns `true` if provided two single-precision floating-point numbers which are the same value', opts, function test( t ) {
	var values;
	var i;

	values = [
		toFloat32( 5.0 ),
		toFloat32( 3.14 ),
		toFloat32( -3.14 ),
		toFloat32( 0.0 ),
		toFloat32( -0.0 ),
		toFloat32( NaN )
	];
	for ( i = 0; i < values.length; i++ ) {
		t.strictEqual( isSameValue( values[ i ], values[ i ] ), true, 'returns expected value when provided '+values[ i ] );
	}
	t.end();
});

tape( 'the function returns `false` if not provided two single-precision floating-point numbers which are the same value', opts, function test( t ) {
	var a;
	var b;
	var i;

	a = [
		toFloat32( 5.0 ),
		toFloat32( 3.14 ),
		toFloat32( -3.14 ),
		toFloat32( 0.0 ),
		toFloat32( -0.0 )
	];
	b = [
		toFloat32( -5.0 ),
		toFloat32( -3.14 ),
		toFloat32( 3.14 ),
		toFloat32( -0.0 ),
		toFloat32( 0.0 )
	];
	for ( i = 0; i < a.length; i++ ) {
		t.strictEqual( isSameValue( a[ i ], b[ i ] ), false, 'returns expected value when provided '+a[ i ]+' and '+b[ i ] );
	}
	t.end();
});","lineStart":1,"lineEnd":86,"totalLines":86,"truncated":false}},"title":"repos\pc-lib-3456\number-float32-base-assert-is-same-value\test\test.native.js","time":{"start":1783695648895,"end":1783695648977}},"id":"prt_f4c8ba1f8001gqYMTyOluCoLWp","sessionID":"ses_0b375922bffeqIp8v5OEVO9ZqY","messageID":"msg_f4c8b66fe001W4TIDahDr549YS"}}

